from collections import Counter, deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    fg=next(v for v in Counter(v for row in grid for v in row) if v!=bg)
    seen=set(); q=deque()
    for r in range(h):
        for c in (0,w-1):
            if grid[r][c]==bg and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c]==bg and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==bg and (nr,nc) not in seen:
                seen.add((nr,nc));q.append((nr,nc))
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg and (r,c) not in seen: out[r][c]=4
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=bg: continue
            if (c>0 and c+1<w and grid[r][c-1]==fg and grid[r][c+1]==fg) or (r>0 and r+1<h and grid[r-1][c]==fg and grid[r+1][c]==fg):
                out[r][c]=4
    return out

